package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.net.MalformedURLException;
import java.net.URL;
import java.util.*;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.parser.Parser;
import org.jsoup.select.NodeTraversor;
import org.jsoup.select.NodeVisitor;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class Node_siblingNodes_TriageGen1Test {

    @Test
    public void testSiblingNodesWithChildren() {
        // Setup a hierarchy: <div id="parent"><p></p><span></span></div>
        Document doc = Document.createShell("");
        Element parent = doc.body();
        Element child1 = new Element(Tag.valueOf("p"), "");
        Element child2 = new Element(Tag.valueOf("span"), "");

        parent.appendChild(child1);
        parent.appendChild(child2);

        // Test siblingNodes on the first child
        List<Node> siblings = child1.siblingNodes();

        // Based on the implementation: return parent().childNodes();
        // The siblings of a node are defined by the parent's child list.
        Assert.assertEquals(2, siblings.size());
        Assert.assertTrue(siblings.contains(child1));
        Assert.assertTrue(siblings.contains(child2));
        Assert.assertEquals(child1, siblings.get(0));
        Assert.assertEquals(child2, siblings.get(1));
    }

    @Test
    public void testSiblingNodesWithSingleChild() {
        Document doc = Document.createShell("");
        Element parent = doc.body();
        Element child1 = new Element(Tag.valueOf("p"), "");
        parent.appendChild(child1);

        List<Node> siblings = child1.siblingNodes();

        Assert.assertEquals(1, siblings.size());
        Assert.assertEquals(child1, siblings.get(0));
    }

    @Test(expected = NullPointerException.class)
    public void testSiblingNodesWithNoParent() {
        // A node with no parent should throw NPE when calling parent().childNodes()
        // because parent() returns null.
        Node orphan = new TextNode("orphan");
        orphan.siblingNodes();
    }

    @Test
    public void testSiblingNodesEmptyParent() {
        // This case is technically impossible if the node has a parent, 
        // but we test the logic via a node that is the only child.
        Document doc = Document.createShell("");
        Element parent = doc.body();
        Element child = new Element(Tag.valueOf("div"), "");
        parent.appendChild(child);

        List<Node> siblings = child.siblingNodes();
        Assert.assertFalse(siblings.isEmpty());
        Assert.assertEquals(child, siblings.get(0));
    }
}
